    13  static UA_Boolean tortureEncoding(const uint8_t *data, size_t size, size_t *newOffset) {
    14      *newOffset = 0;
    15      if (size <= 2)
    16          return UA_FALSE;
    17
    18      // get some random type
    19      uint16_t typeIndex = (uint16_t)(data[0] | data[1] << 8);
    20      data += 2;
    21      size -= 2;
    22
    23      if (typeIndex >= UA_TYPES_COUNT)
    24          return UA_FALSE;
    25
    26      void *dst = UA_new(&UA_TYPES[typeIndex]);
    27
    28      const UA_ByteString binary = {
    29              size, //length
    30              (UA_Byte *) (void *) data
    31      };
    32
    33      UA_StatusCode ret = UA_decodeBinary(&binary, newOffset, dst, &UA_TYPES[typeIndex], NULL);
    34
    35      if (ret == UA_STATUSCODE_GOOD) {
    36          // copy the datatype to test
    37          void *dstCopy = UA_new(&UA_TYPES[typeIndex]);
    38          UA_copy(dst, dstCopy, &UA_TYPES[typeIndex]);
    39          UA_delete(dstCopy, &UA_TYPES[typeIndex]);
    40
    41          // now also test encoding
    42          UA_ByteString encoded;
    43          UA_ByteString_allocBuffer(&encoded, *newOffset);
    44          const UA_Byte *end = &encoded.data[*newOffset];
    45          UA_Byte *pos = encoded.data;
    46          ret = UA_encodeBinary(dst, &UA_TYPES[typeIndex], &pos, &end, NULL, NULL);
    47          if (ret == UA_STATUSCODE_GOOD) {
    48              // do nothing
    49          }
    50          UA_ByteString_deleteMembers(&encoded);
    51      }
    52      UA_delete(dst, &UA_TYPES[typeIndex]);
    53
    54      return UA_TRUE;
    55  }
