    57  static UA_Boolean tortureExtensionObject(const uint8_t *data, size_t size, size_t *newOffset) {
    58      *newOffset = 0;
    59      // check if there is still enough data to create an extension object
    60      // we need at least a nodeid.numeric which equals to 4 bytes
    61      if (size < 4)
    62          return UA_FALSE;
    63
    64      UA_UInt32 identifier = (UA_UInt32)(data[0] | data[1] << 8 | data[2] << 16 | data[3] << 24);
    65      size-= 4;
    66
    67
    68      UA_NodeId objectId = UA_NODEID_NUMERIC(0, identifier);
    69
    70      UA_ExtensionObject obj;
    71      UA_ExtensionObject_init(&obj);
    72      obj.encoding = UA_EXTENSIONOBJECT_ENCODED_BYTESTRING;
    73      obj.content.encoded.typeId = objectId;
    74      obj.content.encoded.body.length = size;
    75      obj.content.encoded.body.data = (UA_Byte*)(void*)data; // discard const. We are sure that we don't change it
    76
    77      const UA_DataType *type = UA_findDataTypeByBinary(&obj.content.encoded.typeId);
    78
    79      UA_StatusCode ret = UA_STATUSCODE_GOOD;
    80      if (type) {
    81          void *dstCopy = UA_new(type);
    82          ret = UA_decodeBinary(&obj.content.encoded.body, newOffset, dstCopy, type, NULL);
    83
    84          if (ret == UA_STATUSCODE_GOOD) {
    85              UA_Variant var;
    86              UA_Variant_init(&var);
    87              UA_Variant_setScalar(&var, dstCopy, type);
    88          }
    89          UA_delete(dstCopy, type);
    90      }
    91      return ret==UA_STATUSCODE_GOOD;
    92  }
