    94  /*
    95  ** Main entry point.  The fuzzer invokes this function with each
    96  ** fuzzed input.
    97  */
    98  extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    99
   100      if (!UA_memoryManager_setLimitFromLast4Bytes(data, size))
   101          return 0;
   102      size -= 4;
   103
   104      size_t offset;
   105      if (!tortureEncoding(data, size, &offset)) {
   106          return 0;
   107      }
   108      if (offset >= size)
   109          return 0;
   110
   111
   112      tortureExtensionObject(&data[offset], size-offset, &offset);
   113
   114
   115      return 0;
   116  }
